module tb; reg clk=0,rst_n=0,start=0; reg[7:0] a,b; wire done; wire[7:0] gcd_out; gcd dut(clk,rst_n,start,a,b,done,gcd_out); always #5 clk=~clk; task run(input[7:0] x,input[7:0] y,input[7:0] e); begin @(negedge clk);a=x;b=y;start=1;@(negedge clk);start=0;wait(done);if(gcd_out!==e)$fatal(1,"gcd");end endtask initial begin repeat(2)@(posedge clk);rst_n=1;run(48,18,6);run(17,13,1);$display("TB_SUMMARY total=2 errors=0");$display("PASS");$finish;end endmodule
